using GraphApi.Models.ANM.LogVisualizacionAnuncios;namespace GraphApi.Services.ANM.LogVisualizacionAnuncios{    /// <summary>    /// Define las operaciones de negocio y persistencia para LogVisualizacionAnuncios.    /// </summary>    public interface ILogVisualizacionAnunciosService    {        /// <summary>        /// Obtiene la lista de LogVisualizacionAnuncios con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadLogVisualizacionAnuncios>> GetLogVisualizacionAnuncios(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de LogVisualizacionAnuncios con filtros opcionales.        /// </summary>        /// <param name="logVisualizacionAnuncioID">Filtro opcional para LogVisualizacionAnuncioID.</param>        /// <param name="anuncioID">Filtro opcional para AnuncioID.</param>        /// <param name="usuarioID">Filtro opcional para UsuarioID.</param>        /// <param name="medio">Filtro opcional para Medio.</param>        /// <param name="iPOrigen">Filtro opcional para IPOrigen.</param>        /// <param name="userAgent">Filtro opcional para UserAgent.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetLogVisualizacionAnunciosDynamic(            int? logVisualizacionAnuncioID,            int? anuncioID,            int? usuarioID,            string? medio,            string? iPOrigen,            string? userAgent,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo LogVisualizacionAnuncio.        /// </summary>        /// <param name="objInput">Datos para crear el LogVisualizacionAnuncio.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadLogVisualizacionAnuncios> CreateLogVisualizacionAnuncios(            clCreateLogVisualizacionAnuncios objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un LogVisualizacionAnuncio.        /// </summary>        /// <param name="objInput">Datos para actualizar el LogVisualizacionAnuncio, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadLogVisualizacionAnuncios?> UpdateLogVisualizacionAnuncios(            clUpdateLogVisualizacionAnuncios objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un LogVisualizacionAnuncio por su ID.        /// </summary>        /// <param name="nLogVisualizacionAnunciosID">ID del LogVisualizacionAnuncio a eliminar.</param>        Task<bool> DeleteLogVisualizacionAnuncios(int nLogVisualizacionAnunciosID);    }}